defmodule Authmk.Schema.PrimaryKey do
  @moduledoc """
  Primary key kinds. Set the default with `primary_key:` in `use Authmk`, and
  override it per model with `schema: [session: [primary_key: ...]]`:

    * `:binary_id` (default): random UUIDs (v4), generated by the app
    * `:uuid_v7`: time-ordered UUIDs, which index better than random ones
    * `:id`: integers from the database's auto-increment
    * `{:string, {module, function, args}}`: string ids from your own function,
      like `{:string, {MyApp.Ids, :generate, []}}`

  Foreign keys follow the referenced model's kind, so models can mix kinds.
  """

  @type t :: :binary_id | :uuid_v7 | :id | {:string, mfa()}

  @doc "NimbleOptions type for primary key options."
  @spec option_type() :: term()
  def option_type,
    do: {:or, [{:in, [:binary_id, :uuid_v7, :id]}, {:tuple, [{:in, [:string]}, :mfa]}]}

  @doc "The Ecto `@primary_key` attribute."
  @spec attribute(t()) :: {:id, atom(), keyword()}
  def attribute(:binary_id), do: {:id, :binary_id, autogenerate: true}
  def attribute(:uuid_v7), do: {:id, Ecto.UUID, autogenerate: [version: 7]}
  def attribute(:id), do: {:id, :id, autogenerate: true}
  def attribute({:string, mfa}), do: {:id, :string, autogenerate: mfa}

  @doc "The Ecto type of foreign keys pointing at this kind."
  @spec ecto_type(t()) :: atom()
  def ecto_type(:binary_id), do: :binary_id
  def ecto_type(:uuid_v7), do: Ecto.UUID
  def ecto_type(:id), do: :id
  def ecto_type({:string, _mfa}), do: :string

  @doc ~s(The column type in migrations: `"binary_id"`, `"id"` or `"string"`.)
  @spec column_type(t()) :: String.t()
  def column_type(kind) when kind in [:binary_id, :uuid_v7], do: "binary_id"
  def column_type(:id), do: "id"
  def column_type({:string, _mfa}), do: "string"

  @doc """
  A new id, for records authmk creates outside the database (sessions kept
  only in secondary storage). `:id` keys come from the database, so they
  can't be generated here.
  """
  @spec generate(t()) :: String.t()
  def generate(:binary_id), do: Ecto.UUID.generate()
  def generate(:uuid_v7), do: Ecto.UUID.generate(version: 7)
  def generate({:string, {module, function, args}}), do: apply(module, function, args)
end
